def clone_repository(repo_url_or_path: str, branch: Optional[str] = None) -> ClonedRepo:
    """Clones a remote git repo or references a local directory."""
    # Check if input is an existing local directory
    if os.path.isdir(repo_url_or_path):
        return ClonedRepo(temp_dir=None, repo_path=os.path.abspath(repo_url_or_path), is_temp=False)

    temp_dir = tempfile.mkdtemp(prefix="contextcore_clone_")
    clone_kwargs = {"depth": 1}
    if branch:
        clone_kwargs["branch"] = branch

    try:
        git.Repo.clone_from(repo_url_or_path, temp_dir, **clone_kwargs)
        return ClonedRepo(temp_dir=temp_dir, repo_path=temp_dir, is_temp=True)
    except Exception as e:
        shutil.rmtree(temp_dir, ignore_errors=True)
        raise RuntimeError(f"Failed to clone repository '{repo_url_or_path}': {str(e)}") from e

def build_chunk_embedding_text(chunk: CodeChunk) -> str:
    """Builds a rich semantic representation of the code chunk for embedding."""
    parts = [
        f"File: {chunk.file_path}",
        f"Symbol: {chunk.symbol_name} (type: {chunk.chunk_type}, lang: {chunk.language})",
        f"Lines: {chunk.start_line}-{chunk.end_line}",
    ]
    if chunk.docstring:
        parts.append(f"Docstring: {chunk.docstring}")
    parts.append(f"Code:\n{chunk.content}")
    return "\n".join(parts)

class Embedder:
    def __init__(self):
        self.api_key = settings.gemini_api_key or os.getenv("GEMINI_API_KEY", "")
        self.model_name = settings.embedding_model
        self.dimension = settings.embedding_dimension
        self.client = None

        if self.api_key:
            if GENAI_V2_AVAILABLE:
                try:
                    self.client = genai.Client(api_key=self.api_key)
                except Exception:
                    self.client = None
            elif LEGACY_GENAI_AVAILABLE:
                try:
                    legacy_genai.configure(api_key=self.api_key)
                except Exception:
                    pass

    def embed_texts(self, texts: List[str], task_type: str = "RETRIEVAL_DOCUMENT") -> List[List[float]]:
        if not texts:
            return []

        # If API key is available, call Gemini Embedding API
        if self.api_key:
            try:
                if self.client and GENAI_V2_AVAILABLE:
                    results = []
                    # Process in batches of 50
                    for i in range(0, len(texts), 50):
                        batch = texts[i : i + 50]
                        response = self.client.models.embed_content(
                            model=self.model_name,
                            contents=batch,
                            config=types.EmbedContentConfig(
                                task_type=task_type,
                                output_dimensionality=self.dimension
                            ) if hasattr(types, "EmbedContentConfig") else None
                        )
                        if hasattr(response, "embeddings"):
                            for emb in response.embeddings:
                                results.append(emb.values)
                    if len(results) == len(texts):
                        return results
                elif LEGACY_GENAI_AVAILABLE:
                    results = []
                    for i in range(0, len(texts), 50):
                        batch = texts[i : i + 50]
                        response = legacy_genai.embed_content(
                            model=f"models/{self.model_name}",
                            content=batch,
                            task_type=task_type
                        )
                        if "embedding" in response:
                            results.extend(response["embedding"])
                    if len(results) == len(texts):
                        return results
            except Exception as e:
                print(f"Warning: Gemini API embedding failed ({e}), falling back to deterministic local embedding.")

        # Fallback to deterministic embedding
        return [fallback_deterministic_embedding(t, self.dimension) for t in texts]

    def embed_chunks(self, chunks: List[CodeChunk]) -> List[List[float]]:
        texts = [build_chunk_embedding_text(c) for c in chunks]
        return self.embed_texts(texts, task_type="RETRIEVAL_DOCUMENT")

    def embed_query(self, query: str) -> List[float]:
        embeddings = self.embed_texts([query], task_type="RETRIEVAL_QUERY")
        return embeddings[0] if embeddings else [0.0] * self.dimension

