def derive_repo_id(repo_url: str) -> str:
    cleaned = repo_url.rstrip("/").removesuffix(".git")
    parts = cleaned.replace("\\", "/").split("/")
    if len(parts) >= 2:
        return f"{parts[-2]}/{parts[-1]}".lower()
    return parts[-1].lower() if parts else "default-repo"

